cat > src/realpath.js <<'EOF'
import fs from 'node:fs';
import path from 'node:path';

// Node ships two realpath implementations:
//   - fs.realpath / fs.realpathSync: a JavaScript reimplementation that walks
//     each path component with lstat/readlink. Its behavior has shifted across
//     releases and differs from the OS on Windows (subst/mapped drives, casing,
//     long paths).
//   - fs.realpath.native / fs.realpathSync.native / fs.promises.realpath: thin
//     wrappers over libuv's uv_fs_realpath, i.e. realpath(3) on POSIX and
//     GetFinalPathNameByHandleW on Windows.
// We always use the native variant so the result is whatever the OS considers
// canonical, independent of the Node version running the script.

/**
 * Resolve `p` (relative paths are resolved against `cwd`) to its canonical
 * path, following every symlink. The target must exist.
 * @param {string} p
 * @param {{ cwd?: string }} [options]
 * @returns {Promise<string>}
 */
export async function resolveRealPath(p, { cwd = process.cwd() } = {}) {
  return fs.promises.realpath(toAbsolute(p, cwd));
}

/**
 * Synchronous variant of {@link resolveRealPath}.
 * @param {string} p
 * @param {{ cwd?: string }} [options]
 * @returns {string}
 */
export function resolveRealPathSync(p, { cwd = process.cwd() } = {}) {
  return fs.realpathSync.native(toAbsolute(p, cwd));
}

function toAbsolute(p, cwd) {
  if (typeof p !== 'string' || p === '') {
    throw new TypeError('path must be a non-empty string');
  }
  return path.resolve(cwd, p);
}
EOF
cat > bin/resolve-realpath.js <<'EOF'
#!/usr/bin/env node
import { resolveRealPath } from '../src/realpath.js';

const args = process.argv.slice(2);
if (args.length === 0 || args.includes('-h') || args.includes('--help')) {
  console.error('Usage: resolve-realpath <path> [path...]');
  process.exit(args.length === 0 ? 1 : 0);
}

let failed = false;
for (const arg of args) {
  try {
    console.log(await resolveRealPath(arg));
  } catch (err) {
    failed = true;
    const reason = {
      ENOENT: 'no such file or directory',
      ELOOP: 'too many levels of symbolic links',
      EACCES: 'permission denied',
      ENOTDIR: 'a path component is not a directory',
    }[err.code] ?? err.message;
    console.error(`resolve-realpath: ${arg}: ${reason}`);
  }
}
process.exit(failed ? 1 : 0);
EOF
chmod +x bin/resolve-realpath.js
cat > test/realpath.test.js <<'EOF'
import { test, before, after } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { resolveRealPath, resolveRealPathSync } from '../src/realpath.js';

let root;

before(() => {
  // tmpdir itself may be a symlink (e.g. /tmp -> /private/tmp on macOS).
  root = fs.realpathSync.native(fs.mkdtempSync(path.join(os.tmpdir(), 'realpath-')));
  fs.mkdirSync(path.join(root, 'real/nested'), { recursive: true });
  fs.writeFileSync(path.join(root, 'real/nested/file.txt'), 'x');
  fs.symlinkSync(path.join(root, 'real'), path.join(root, 'dirlink'), 'dir');
  fs.symlinkSync('dirlink/nested/file.txt', path.join(root, 'filelink'));
  fs.symlinkSync('filelink', path.join(root, 'chain'));
  fs.symlinkSync('loop-b', path.join(root, 'loop-a'));
  fs.symlinkSync('loop-a', path.join(root, 'loop-b'));
  fs.symlinkSync('missing', path.join(root, 'dangling'));
});

after(() => fs.rmSync(root, { recursive: true, force: true }));

const expected = () => path.join(root, 'real/nested/file.txt');

for (const [name, fn] of [['async', resolveRealPath], ['sync', resolveRealPathSync]]) {
  test(`${name}: resolves a symlinked directory component`, async () => {
    assert.equal(await fn(path.join(root, 'dirlink/nested/file.txt')), expected());
  });

  test(`${name}: resolves a chain of relative file symlinks`, async () => {
    assert.equal(await fn(path.join(root, 'chain')), expected());
  });

  test(`${name}: resolves relative input against cwd and normalizes ..`, async () => {
    assert.equal(await fn('dirlink/nested/../nested/file.txt', { cwd: root }), expected());
  });

  test(`${name}: rejects dangling symlinks with ENOENT`, async () => {
    await assert.rejects(async () => fn(path.join(root, 'dangling')), { code: 'ENOENT' });
  });

  test(`${name}: rejects symlink loops with ELOOP`, async () => {
    await assert.rejects(async () => fn(path.join(root, 'loop-a')), { code: 'ELOOP' });
  });

  test(`${name}: rejects empty input`, async () => {
    await assert.rejects(async () => fn(''), TypeError);
  });
}
EOF
cat > .gitignore <<'EOF'
node_modules/
EOF
npm test 2>&1 | tail -15
ln -sfn src /tmp/srclink && node bin/resolve-realpath.js /tmp/srclink/realpath.js /nope; echo "exit=$?"; rm /tmp/srclink

